/**
 * Construct an AudioWorklet node, translating the one failure the browser
 * words badly.
 *
 * `audioWorklet.addModule` resolves even when the module's top-level code
 * throws: the browser reports that as an unhandled error inside the
 * AudioWorkletGlobalScope rather than as a load failure. So a processor that
 * failed to register only shows up when the node is constructed, as "the node
 * name '<name>' is not defined", which reads as a naming or loading problem
 * and says nothing about the real cause. Point the caller at the worklet
 * console, where the actual error is.
 *
 * @param processorName the name the module was expected to register
 * @param create constructs the node
 * @param usualCause appended to the message, for the failure most likely here
 */
const createWorkletNode = <N>(
    processorName: string,
    create: () => N,
    usualCause = ''
): N => {
    try {
        return create();
    } catch (error) {
        throw new Error(
            `Faust: the AudioWorkletProcessor "${processorName}" did not register. ` +
                `The module loaded, so the failure happened while it ran — ` +
                `its error is reported in the AudioWorklet scope and appears in the ` +
                `browser console above this one.${usualCause ? ` ${usualCause}` : ''} ` +
                `Original error: ${error instanceof Error ? error.message : String(error)}`
        );
    }
};

export interface GeneratorSupportingSoundfiles {
    /**
     * Attach a map of id - audio data, call after `compile()` before `createNode()`
     *
     * @param soundfileMap a map of id - `AudioData` as an object where `AudioData` contains channel data as `audioBuffer: Float32Array[]` and `sampleRate: number`
     */
    addSoundfiles(soundfileMap: Record<string, AudioData>): void;

    /**
     * Get a list of soundfiles needed, call after `compile()`
     */
    getSoundfileList(): string[];
}

export interface IFaustDspGenerator {
    /**
     * Create a monophonic or polyphonic WebAudio node (either ScriptProcessorNode or AudioWorkletNode).
     * Analyze the code to decide whether to create a monophonic or polyphonic node.
     *
     * @param context - the WebAudio context
     * @param name - DSP name, can be used for processorName
     * @param code - the DSP code
     * @param sp - whether to compile a ScriptProcessorNode or an AudioWorkletNode
     * @param bufferSize - the buffer size in frames to be used in ScriptProcessorNode only, since AudioWorkletNode always uses 128 frames
     * @returns the compiled monophonic or polyphonic WebAudio node or 'null' if failure
     */
    createFaustNode(
        context: BaseAudioContext,
        name: string,
        code: string,
        sp?: boolean,
        bufferSize?: number
    ): Promise<IFaustMonoWebAudioNode | IFaustPolyWebAudioNode | null>;
}

export interface IFaustMonoDspGenerator extends GeneratorSupportingSoundfiles {
    /**
     * Compile a monophonic DSP factory from given code.
     *
     * @param compiler - the Faust compiler
     * @param name - the DSP name
     * @param code - the DSP code
     * @param args - the compilation parameters
     * @returns the compiled factory or 'null' if failure
     */
    compile(
        compiler: IFaustCompiler,
        name: string,
        code: string,
        args: string
    ): Promise<{
        factory: FaustDspFactory | null;
        name?: string;
        meta?: FaustDspMeta;
    } | null>;

    /**
     * Create a monophonic WebAudio node (either ScriptProcessorNode or AudioWorkletNode).
     *
     * @param context - the WebAudio context
     * @param name - DSP name, can be used for processorName
     * @param factory - default is the compiled factory
     * @param sp - whether to compile a ScriptProcessorNode or an AudioWorkletNode
     * @param bufferSize - the buffer size in frames to be used in ScriptProcessorNode only, since AudioWorkletNode always uses 128 frames
     * @param processorName - AudioWorklet Processor name
     * @param processorOptions - Additional AudioWorklet Processor options
     * @returns the compiled WebAudio node or 'null' if failure
     */
    createNode(
        context: BaseAudioContext,
        name?: string,
        factory?: LooseFaustDspFactory,
        sp?: boolean,
        bufferSize?: number,
        processorName?: string,
        processorOptions?: Record<string, any>
    ): Promise<IFaustMonoWebAudioNode | null>;

    /**
     * Create a monophonic WebAudio node (either ScriptProcessorNode or AudioWorkletNode).
     *
     * @param context - the WebAudio context
     * @param fftUtils - should be an anonymous class with static methods, without any import from outside
     * @param name - DSP name, can be used for processorName
     * @param factory - default is the compiled factory
     * @param fftOptions - initial FFT options
     * @param processorName - AudioWorklet Processor name
     * @param processorOptions - Additional AudioWorklet Processor options
     * @returns the compiled WebAudio node or 'null' if failure
     */
    createFFTNode(
        context: BaseAudioContext,
        fftUtils: typeof FFTUtils,
        name?: string,
        factory?: LooseFaustDspFactory,
        fftOptions?: Partial<FaustFFTOptionsData>,
        processorName?: string,
        processorOptions?: Record<string, any>
    ): Promise<FaustMonoAudioWorkletNode | null>;

    /**
     * Create a monophonic Offline processor.
     *
     * @param sampleRate - the sample rate in Hz
     * @param bufferSize - the buffer size in frames
     * @param factory - default is the compiled factory
     * @param context - if this exists, will be used to fetch soundfiles online
     * @returns the compiled processor or 'null' if failure
     */
    createOfflineProcessor(
        sampleRate: number,
        bufferSize: number,
        factory?: LooseFaustDspFactory,
        context?: BaseAudioContext
    ): Promise<IFaustMonoOfflineProcessor | null>;

    /**
     * Get DSP JSON description with its UI and metadata as object.
     *
     * @return the DSP JSON description as object
     */
    getMeta(): FaustDspMeta;

    /**
     * Get DSP JSON description with its UI and metadata.
     *
     * @return the DSP JSON description
     */
    getJSON(): string;

    /**
     * Get DSP UI description.
     *
     * @return the DSP UI description
     */
    getUI(): FaustUIDescriptor;
}

export interface IFaustPolyDspGenerator extends GeneratorSupportingSoundfiles {
    /**
     * Compile a monophonic DSP factory from given code.
     *
     * @param compiler - the Faust compiler
     * @param name - the DSP name
     * @param dspCode - the DSP code ('dspCode' can possibly contain an integrated effect)
     * @param args - the compilation parameters
     * @param effectCode - optional effect DSP code
     * @returns the compiled factory or 'null' if failure
     */
    compile(
        compiler: IFaustCompiler,
        name: string,
        dspCode: string,
        args: string,
        effectCode?: string
    ): Promise<{
        voiceFactory: FaustDspFactory | null;
        effectFactory?: FaustDspFactory | null;
    } | null>;

    /**
     * Create a polyphonic WebAudio node (either ScriptProcessorNode or AudioWorkletNode).
     *
     * @param context the WebAudio context
     * @param voices - the number of voices
     * @param name - AudioWorklet Processor name
     * @param voiceFactory - the Faust factory for voices, either obtained with a compiler (createDSPFactory) or loaded from files (loadDSPFactory)
     * @param mixerModule - the wasm Mixer module (loaded from 'mixer32.wasm' or 'mixer64.wasm' files located in the 'faustwasm' package)
     * @param effectFactory - the Faust factory for the effect, either obtained with a compiler (createDSPFactory) or loaded from files (loadDSPFactory)
     * @param sp - whether to compile a ScriptProcessorNode or an AudioWorkletNode
     * @param bufferSize - the buffer size in frames to be used in ScriptProcessorNode only, since AudioWorkletNode always uses 128 frames
     * @param processorOptions - Additional AudioWorklet Processor options. Its `stopLevel`, used by the ScriptProcessorNode too,
     * is the level under which a released voice is freed: a linear amplitude (10^(dB/20)) in ]0, 0.01], compared to the RMS level
     * of the voice on each block. It defaults to -90 dB, as any value outside that range does.
     * @returns the compiled WebAudio node or 'null' if failure
     */
    createNode(
        context: BaseAudioContext,
        voices: number,
        name?: string,
        voiceFactory?: LooseFaustDspFactory,
        mixerModule?: WebAssembly.Module,
        effectFactory?: LooseFaustDspFactory | null,
        sp?: boolean,
        bufferSize?: number,
        processorName?: string,
        processorOptions?: Record<string, any>
    ): Promise<IFaustPolyWebAudioNode | null>;

    /**
     * Create a monophonic Offline processor.
     *
     * @param sampleRate - the sample rate in Hz
     * @param bufferSize - the buffer size in frames
     * @param voiceFactory - the Faust factory for voices, either obtained with a compiler (createDSPFactory) or loaded from files (loadDSPFactory)
     * @param mixerModule - the wasm Mixer module (loaded from 'mixer32.wasm' or 'mixer64.wasm' files)
     * @param effectFactory - the Faust factory for the effect, either obtained with a compiler (createDSPFactory) or loaded from files (loadDSPFactory)
     * @param context - if this exists, will be used to fetch soundfiles online
     * @param stopLevel - the level under which a released voice is freed: a linear amplitude (10^(dB/20)) in ]0, 0.01],
     * compared to the RMS level of the voice on each block. It defaults to -90 dB, as any value outside that range does.
     * @returns the compiled processor or 'null' if failure
     */
    createOfflineProcessor(
        sampleRate: number,
        bufferSize: number,
        voices: number,
        voiceFactory?: LooseFaustDspFactory,
        mixerModule?: WebAssembly.Module,
        effectFactory?: LooseFaustDspFactory | null,
        context?: BaseAudioContext,
        stopLevel?: number
    ): Promise<IFaustPolyOfflineProcessor | null>;

    /**
     * Get DSP JSON description with its UI and metadata as object.
     *
     * @return the DSP JSON description as object
     */
    getMeta(): FaustDspMeta;

    /**
     * Get DSP JSON description with its UI and metadata.
     *
     * @return the DSP JSON description
     */
    getJSON(): string;

    /**
     * Get DSP UI description.
     *
     * @return the DSP UI description
     */
    getUI(): FaustUIDescriptor;
}

export class FaustMonoDspGenerator implements IFaustMonoDspGenerator {
    // Set of all created WorkletProcessors, each of them has to be unique
    private static gWorkletProcessors: Map<BaseAudioContext, Set<string>> =
        new Map();

    name: string;
    factory!: FaustDspFactory | null;

    constructor() {
        this.factory = null;
    }
    async compile(
        compiler: IFaustCompiler,
        name: string,
        code: string,
        args: string
    ) {
        this.factory = await compiler.createMonoDSPFactory(name, code, args);
        if (this.factory) {
            this.name = name;
            return this;
        } else {
            return null;
        }
    }

    addSoundfiles(soundfileMap: Record<string, AudioData>) {
        if (!this.factory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );
        for (const id in soundfileMap) {
            this.factory.soundfiles[id] = soundfileMap[id];
        }
    }
    getSoundfileList() {
        if (!this.factory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );
        const meta = JSON.parse(this.factory.json);
        const map = SoundfileReader.findSoundfilesFromMeta(meta);
        if (!map) return [];
        return Object.keys(map);
    }

    async createNode<SP extends boolean = false>(
        context: BaseAudioContext,
        name = this.name,
        factory = this.factory as LooseFaustDspFactory,
        sp = false as SP,
        bufferSize = 1024,
        processorName = factory?.shaKey || name,
        processorOptions: Record<string, any> = {}
    ): Promise<
        SP extends true
            ? FaustMonoScriptProcessorNode | null
            : FaustMonoAudioWorkletNode | null
    > {
        if (!factory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const meta = JSON.parse(factory.json);
        const sampleSize = meta.compile_options.match('-double') ? 8 : 4;
        factory.soundfiles = await SoundfileReader.loadSoundfiles(
            meta,
            factory.soundfiles || {},
            context
        );
        if (sp) {
            const instance =
                await FaustWasmInstantiator.createAsyncMonoDSPInstance(factory);
            const monoDsp = new FaustMonoWebAudioDsp(
                instance,
                context.sampleRate,
                sampleSize,
                bufferSize,
                factory.soundfiles
            );

            const sp = context.createScriptProcessor(
                bufferSize,
                monoDsp.getNumInputs(),
                monoDsp.getNumOutputs()
            ) as FaustMonoScriptProcessorNode;
            Object.setPrototypeOf(sp, FaustMonoScriptProcessorNode.prototype);
            sp.setupNode(monoDsp);
            return sp as SP extends true
                ? FaustMonoScriptProcessorNode
                : FaustMonoAudioWorkletNode;
        } else {
            // Dynamically create AudioWorkletProcessor if code not yet created
            if (!FaustMonoDspGenerator.gWorkletProcessors.has(context))
                FaustMonoDspGenerator.gWorkletProcessors.set(
                    context,
                    new Set()
                );
            if (
                !FaustMonoDspGenerator.gWorkletProcessors
                    .get(context)
                    ?.has(processorName)
            ) {
                const processorCode = `
// DSP name and JSON string for DSP are generated
const faustData = ${JSON.stringify({
                    processorName,
                    dspName: name,
                    dspMeta: meta,
                    poly: false
                } as FaustData)};
// The processor itself, bundled at this package's build time into one
// self-contained string (see build-worklets.js), so that no bundler minifying
// the application can break its internal references.
${monoProcessorSource}
`;
                const url = URL.createObjectURL(
                    new Blob([processorCode], { type: 'text/javascript' })
                );
                // Fails when the page is not served from a secure origin
                // (https, or localhost): the classic cause here.
                await context.audioWorklet.addModule(url);
                // Keep the DSP name
                FaustMonoDspGenerator.gWorkletProcessors
                    .get(context)
                    ?.add(processorName);
            }
            // Create the AWN
            const node = createWorkletNode(
                processorName,
                () =>
                    new FaustMonoAudioWorkletNode(context, {
                        processorOptions: {
                            name: processorName,
                            factory,
                            sampleSize,
                            ...processorOptions
                        }
                    })
            );

            return node as SP extends true
                ? FaustMonoScriptProcessorNode
                : FaustMonoAudioWorkletNode;
        }
    }

    async createFFTNode(
        context: BaseAudioContext,
        fftUtils: typeof FFTUtils,
        name = this.name,
        factory = this.factory as LooseFaustDspFactory,
        fftOptions: Partial<FaustFFTOptionsData> = {},
        processorName = factory?.shaKey ? `${factory.shaKey}_fft` : name,
        processorOptions: Record<string, any> = {}
    ): Promise<FaustMonoAudioWorkletNode | null> {
        if (!factory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const meta: FaustDspMeta = JSON.parse(factory.json);
        const sampleSize = meta.compile_options.match('-double') ? 8 : 4;
        factory.soundfiles = await SoundfileReader.loadSoundfiles(
            meta,
            factory.soundfiles || {},
            context
        );
        // Dynamically create AudioWorkletProcessor if code not yet created
        if (!FaustMonoDspGenerator.gWorkletProcessors.has(context))
            FaustMonoDspGenerator.gWorkletProcessors.set(context, new Set());
        if (
            !FaustMonoDspGenerator.gWorkletProcessors
                .get(context)
                ?.has(processorName)
        ) {
            const processorCode = `
// DSP name and JSON string for DSP are generated
const faustData = ${JSON.stringify({
                processorName,
                dspName: name,
                dspMeta: meta,
                fftOptions
            } as FaustFFTData)};
// The caller's FFT implementation
var FFTUtils = ${fftUtils.toString()};
// The processor itself, bundled at this package's build time into one
// self-contained string (see build-worklets.js), so that no bundler minifying
// the application can break its internal references.
${fftProcessorSource}
`;
            const url = URL.createObjectURL(
                new Blob([processorCode], { type: 'text/javascript' })
            );
            // Fails when the page is not served from a secure origin
            // (https, or localhost): the classic cause here.
            await context.audioWorklet.addModule(url);
            // Keep the DSP name
            FaustMonoDspGenerator.gWorkletProcessors
                .get(context)
                ?.add(processorName);
        }
        // Create the AWN
        const node = createWorkletNode(
            processorName,
            () =>
                new FaustMonoAudioWorkletNode(context, {
                    channelCount: Math.max(1, Math.ceil(meta.inputs / 3)),
                    outputChannelCount: [Math.ceil(meta.outputs / 2)],
                    processorOptions: {
                        name: processorName,
                        factory,
                        sampleSize,
                        ...processorOptions
                    }
                }),
            'The `FFTUtils` class passed to `createFFTNode` runs there too, ' +
                'from its source text alone: it may not refer to anything ' +
                'outside its own body.'
        );
        if (fftOptions.fftSize) {
            const param = node.parameters.get('fftSize');
            if (param) param.value = fftOptions.fftSize;
        }
        if (fftOptions.fftOverlap) {
            const param = node.parameters.get('fftOverlap');
            if (param) param.value = fftOptions.fftOverlap;
        }
        if (typeof fftOptions.defaultWindowFunction === 'number') {
            const param = node.parameters.get('windowFunction');
            if (param) param.value = fftOptions.defaultWindowFunction + 1;
        }
        if (typeof fftOptions.noIFFT === 'boolean') {
            const param = node.parameters.get('noIFFT');
            if (param) param.value = +fftOptions.noIFFT;
        }
        return node;
    }

    async createAudioWorkletProcessor(
        name = this.name,
        factory = this.factory as LooseFaustDspFactory,
        processorName = factory?.shaKey || name
    ) {
        if (!factory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const meta = JSON.parse(factory.json);
        const dependencies = {
            FaustBaseWebAudioDsp,
            FaustMonoWebAudioDsp,
            FaustWasmInstantiator,
            FaustAudioWorkletProcessorCommunicator,
            FaustPolyWebAudioDsp: undefined,
            FaustWebAudioDspVoice: undefined
        };
        // const sampleSize = meta.compile_options.match("-double") ? 8 : 4;
        // Dynamically create AudioWorkletProcessor if code not yet created
        // DSP name and JSON string for DSP are generated
        const faustData = {
            processorName,
            dspName: name,
            dspMeta: meta,
            poly: false
        } as FaustData;
        // Generate the actual AudioWorkletProcessor code
        const Processor = getFaustAudioWorkletProcessor(
            dependencies,
            faustData
        );
        return Processor;
    }

    async createOfflineProcessor(
        sampleRate: number,
        bufferSize: number,
        factory = this.factory as LooseFaustDspFactory,
        context?: BaseAudioContext
    ) {
        if (!factory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const meta = JSON.parse(factory.json);
        const instance =
            await FaustWasmInstantiator.createAsyncMonoDSPInstance(factory);
        const sampleSize = meta.compile_options.match('-double') ? 8 : 4;
        if (context)
            factory.soundfiles = await SoundfileReader.loadSoundfiles(
                meta,
                factory.soundfiles || {},
                context
            );
        const monoDsp = new FaustMonoWebAudioDsp(
            instance,
            sampleRate,
            sampleSize,
            bufferSize,
            factory.soundfiles
        );
        return new FaustMonoOfflineProcessor(monoDsp, bufferSize);
    }

    getMeta() {
        return JSON.parse(this.factory!.json);
    }
    getJSON() {
        return JSON.stringify(this.getMeta());
    }
    getUI() {
        return this.getMeta().ui;
    }
}

export class FaustPolyDspGenerator implements IFaustPolyDspGenerator {
    // Set of all created WorkletProcessors, each of them has to be unique
    private static gWorkletProcessors: Map<BaseAudioContext, Set<string>> =
        new Map();

    name: string;
    voiceFactory!: FaustDspFactory | null;
    effectFactory!: FaustDspFactory | null;
    mixerBuffer!: Uint8Array;
    mixerModule!: WebAssembly.Module;

    constructor() {
        this.voiceFactory = null;
        this.effectFactory = null;
    }
    async compile(
        compiler: IFaustCompiler,
        name: string,
        dspCodeAux: string,
        args: string,
        // The ${dspCode} has to be added with wrapping new lines to make it properly formatted and ready to compile
        effectCodeAux = `dsp_code = environment{
                ${dspCodeAux}
            };
            process = dsp_code.effect;`
    ) {
        // Try to compile effect, possibly failing
        try {
            this.effectFactory = await compiler.createPolyDSPFactory(
                name,
                effectCodeAux,
                args
            );
            // Since the effect is processing the same buffers for inputs and outputs (in place processing),
            // the voice and effect are adapted, possibly clearing buffers
            if (this.effectFactory) {
                const effectJSON = JSON.parse(this.effectFactory.json);
                const ins = effectJSON.inputs;
                const outs = effectJSON.outputs;
                // The voice, the effect inputs and the effect outputs share the mixing buffers,
                // whose width is the largest of the three counts. 'adapt' is the adaptor of
                // poly-dsp.h getEffectCode: split (<:) when there are at least as many inputs,
                // merge (:>) otherwise, so one count must be a multiple of the other.
                const adaptors = `\
bus(n) = par(i,n,_);
pad(n,w) = bus(n), par(i,w-n,0);
width(F) = max(outputs(F), max(${ins},${outs}));
adapt(1,n,m) = bus(n) <: bus(m);
adapt(0,n,m) = bus(n) :> bus(m);
// n channels to w: split when the effect takes w inputs, padded with silent channels otherwise
widen(1,d,n,w) = bus(n);
widen(0,1,n,w) = adapt(1,n,w);
widen(0,0,n,w) = pad(n,w);
// the voice's n channels out of the w of the buffers, the silent ones dropped
real(1,n,w) = bus(n);
real(0,n,w) = bus(n), par(i,w-n,!);
// the w channels to the effect's e inputs: the voice's own channels adapted to them
narrow(1,n,w,e) = bus(w);
narrow(0,n,w,e) = real(n == w, n, w) : adapt(n <= e, n, e);
`;
                const dspCode = `\
${adaptors}
adaptor(F) = widen(outputs(F) == width(F), ${ins} == width(F), outputs(F), width(F));
dsp_code = environment{
    ${dspCodeAux}
};
process = dsp_code.process : adaptor(dsp_code.process);
`;
                const effectCode = `\
${adaptors}
adaptorIns(F) = narrow(width(F) == ${ins}, outputs(F), width(F), ${ins});
adaptorOuts(F) = widen(${outs} == width(F), 0, ${outs}, width(F));
dsp_code = environment{
    ${dspCodeAux}
};
process = adaptorIns(dsp_code.process) : dsp_code.effect : adaptorOuts(dsp_code.process);
`;
                this.voiceFactory = await compiler.createPolyDSPFactory(
                    name,
                    dspCode,
                    args
                );
                try {
                    // Effect is processing same buffers for inputs and outputs, so has to use -inpl option
                    this.effectFactory = await compiler.createPolyDSPFactory(
                        name,
                        effectCode,
                        args + ' -inpl'
                    );
                } catch (e) {
                    // The effect cannot be adapted to the voice: the voice is rendered without it,
                    // rather than with an effect that does not fit its buffers
                    console.warn(e);
                    this.effectFactory = null;
                    this.voiceFactory = await compiler.createPolyDSPFactory(
                        name,
                        dspCodeAux,
                        args
                    );
                }
            }
        } catch (e) {
            // Hack to detect 'undefined effect' symbol error, when no effect is defined in the polyphonic code.
            // The error message is not printed to avoid confusing the user.
            const errorMessage =
                e instanceof Error ? e.message : String(e ?? 'unknown error');
            if (!errorMessage.includes('undefined symbol : effect')) {
                console.warn(e);
            }
            // An effect compiled alone but not adapted to the voice is not used
            this.effectFactory = null;
            this.voiceFactory = await compiler.createPolyDSPFactory(
                name,
                dspCodeAux,
                args
            );
        }

        if (this.voiceFactory) {
            this.name = name;
            const voiceMeta = JSON.parse(this.voiceFactory.json);
            const isDouble = voiceMeta.compile_options.match('-double');
            const { mixerBuffer, mixerModule } =
                await compiler.getAsyncInternalMixerModule(!!isDouble);
            this.mixerBuffer = mixerBuffer;
            this.mixerModule = mixerModule;
            return this;
        } else {
            return null;
        }
    }

    addSoundfiles(soundfileMap: Record<string, AudioData>) {
        if (!this.voiceFactory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );
        for (const id in soundfileMap) {
            this.voiceFactory.soundfiles[id] = soundfileMap[id];
        }
    }
    getSoundfileList() {
        if (!this.voiceFactory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );
        const meta = JSON.parse(this.voiceFactory.json);
        const map = SoundfileReader.findSoundfilesFromMeta(meta);
        if (!map) return [];
        if (!this.effectFactory) return Object.keys(map);
        const effectMeta = JSON.parse(this.effectFactory.json);
        const effectMap = SoundfileReader.findSoundfilesFromMeta(effectMeta);
        return Object.keys({ ...effectMap, ...map });
    }

    async createNode<SP extends boolean = false>(
        context: BaseAudioContext,
        voices: number,
        name = this.name,
        voiceFactory = this.voiceFactory as LooseFaustDspFactory,
        mixerModule = this.mixerModule,
        effectFactory = this.effectFactory as LooseFaustDspFactory | null,
        sp = false as SP,
        bufferSize = 1024,
        processorName = (voiceFactory?.shaKey || '') +
            (effectFactory?.shaKey || '') || `${name}_poly`,
        processorOptions: Record<string, any> = {}
    ): Promise<
        SP extends true
            ? FaustPolyScriptProcessorNode | null
            : FaustPolyAudioWorkletNode | null
    > {
        if (!voiceFactory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const voiceMeta = JSON.parse(voiceFactory.json);
        const effectMeta = effectFactory
            ? JSON.parse(effectFactory.json)
            : undefined;
        const sampleSize = voiceMeta.compile_options.match('-double') ? 8 : 4;
        voiceFactory.soundfiles = await SoundfileReader.loadSoundfiles(
            voiceMeta,
            voiceFactory.soundfiles || {},
            context
        );
        if (effectFactory)
            effectFactory.soundfiles = await SoundfileReader.loadSoundfiles(
                effectMeta,
                effectFactory.soundfiles || {},
                context
            );
        if (sp) {
            const instance =
                await FaustWasmInstantiator.createAsyncPolyDSPInstance(
                    voiceFactory,
                    mixerModule,
                    voices,
                    effectFactory || undefined
                );
            const soundfiles = {
                ...effectFactory?.soundfiles,
                ...voiceFactory.soundfiles
            };
            // The AudioWorklet processor reads the same option
            const polyDsp = new FaustPolyWebAudioDsp(
                instance,
                context.sampleRate,
                sampleSize,
                bufferSize,
                soundfiles,
                processorOptions.stopLevel
            );

            const sp = context.createScriptProcessor(
                bufferSize,
                polyDsp.getNumInputs(),
                polyDsp.getNumOutputs()
            ) as FaustPolyScriptProcessorNode;
            Object.setPrototypeOf(sp, FaustPolyScriptProcessorNode.prototype);
            sp.setupNode(polyDsp);
            return sp as SP extends true
                ? FaustPolyScriptProcessorNode
                : FaustPolyAudioWorkletNode;
        } else {
            // Dynamically create AudioWorkletProcessor if code not yet created
            if (!FaustPolyDspGenerator.gWorkletProcessors.has(context))
                FaustPolyDspGenerator.gWorkletProcessors.set(
                    context,
                    new Set()
                );
            if (
                !FaustPolyDspGenerator.gWorkletProcessors
                    .get(context)
                    ?.has(processorName)
            ) {
                const processorCode = `
// DSP name and JSON string for DSP are generated
const faustData = ${JSON.stringify({
                    processorName,
                    dspName: name,
                    dspMeta: voiceMeta,
                    poly: true,
                    effectMeta
                } as FaustData)};
// The processor itself, bundled at this package's build time into one
// self-contained string (see build-worklets.js), so that no bundler minifying
// the application can break its internal references.
${polyProcessorSource}
`;
                const url = URL.createObjectURL(
                    new Blob([processorCode], { type: 'text/javascript' })
                );
                // Fails when the page is not served from a secure origin
                // (https, or localhost): the classic cause here.
                await context.audioWorklet.addModule(url);
                // Keep the DSP name
                FaustPolyDspGenerator.gWorkletProcessors
                    .get(context)
                    ?.add(processorName);
            }
            // Create the AWN
            const node = createWorkletNode(
                processorName,
                () =>
                    new FaustPolyAudioWorkletNode(context, {
                        processorOptions: {
                            name: processorName,
                            voiceFactory,
                            mixerModule,
                            voices,
                            sampleSize,
                            effectFactory: effectFactory || undefined,
                            ...processorOptions
                        }
                    }),
                'A duplicate control path shared between `process` and ' +
                    '`effect` is the usual cause.'
            );

            return node as SP extends true
                ? FaustPolyScriptProcessorNode
                : FaustPolyAudioWorkletNode;
        }
    }

    async createAudioWorkletProcessor(
        name = this.name,
        voiceFactory = this.voiceFactory as LooseFaustDspFactory,
        effectFactory = this.effectFactory as LooseFaustDspFactory | null,
        processorName = (voiceFactory?.shaKey || '') +
            (effectFactory?.shaKey || '') || `${name}_poly`
    ) {
        if (!voiceFactory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const voiceMeta = JSON.parse(voiceFactory.json);
        const effectMeta = effectFactory
            ? JSON.parse(effectFactory.json)
            : undefined;
        // Dynamically create AudioWorkletProcessor if code not yet created
        const dependencies = {
            FaustBaseWebAudioDsp,
            FaustMonoWebAudioDsp: undefined,
            FaustWasmInstantiator,
            FaustPolyWebAudioDsp,
            FaustWebAudioDspVoice,
            FaustAudioWorkletProcessorCommunicator
        };
        // DSP name and JSON string for DSP are generated
        const faustData = {
            processorName,
            dspName: name,
            dspMeta: voiceMeta,
            poly: true,
            effectMeta
        } as FaustData;
        // Generate the actual AudioWorkletProcessor code
        const Processor = getFaustAudioWorkletProcessor<true>(
            dependencies,
            faustData
        );
        return Processor;
    }

    async createOfflineProcessor(
        sampleRate: number,
        bufferSize: number,
        voices: number,
        voiceFactory = this.voiceFactory as LooseFaustDspFactory,
        mixerModule = this.mixerModule,
        effectFactory = this.effectFactory as LooseFaustDspFactory | null,
        context?: BaseAudioContext,
        stopLevel?: number
    ) {
        if (!voiceFactory)
            throw new Error(
                'Code is not compiled, please define the factory or call `await this.compile()` first.'
            );

        const voiceMeta = JSON.parse(voiceFactory.json);
        const effectMeta = effectFactory
            ? JSON.parse(effectFactory.json)
            : undefined;
        const instance = await FaustWasmInstantiator.createAsyncPolyDSPInstance(
            voiceFactory,
            mixerModule,
            voices,
            effectFactory || undefined
        );
        const sampleSize = voiceMeta.compile_options.match('-double') ? 8 : 4;
        if (context) {
            voiceFactory.soundfiles = await SoundfileReader.loadSoundfiles(
                voiceMeta,
                voiceFactory.soundfiles || {},
                context
            );
            if (effectFactory)
                effectFactory.soundfiles = await SoundfileReader.loadSoundfiles(
                    effectMeta,
                    effectFactory.soundfiles || {},
                    context
                );
        }
        const soundfiles = {
            ...effectFactory?.soundfiles,
            ...voiceFactory.soundfiles
        };
        const polyDsp = new FaustPolyWebAudioDsp(
            instance,
            sampleRate,
            sampleSize,
            bufferSize,
            soundfiles,
            stopLevel
        );
        return new FaustPolyOfflineProcessor(polyDsp, bufferSize);
    }

    getMeta() {
        const o = this.voiceFactory ? JSON.parse(this.voiceFactory.json) : null;
        const e = this.effectFactory
            ? JSON.parse(this.effectFactory.json)
            : null;
        const r = { ...o };
        if (e) {
            r.ui = [
                {
                    type: 'tgroup',
                    label: 'Sequencer',
                    items: [
                        { type: 'vgroup', label: 'Instrument', items: o.ui },
                        { type: 'vgroup', label: 'Effect', items: e.ui }
                    ]
                }
            ];
        } else {
            r.ui = [
                {
                    type: 'tgroup',
                    label: 'Polyphonic',
                    items: [{ type: 'vgroup', label: 'Voices', items: o.ui }]
                }
            ];
        }
        return r as FaustDspMeta;
    }

    getJSON() {
        return JSON.stringify(this.getMeta());
    }

    getUI() {
        return this.getMeta().ui;
    }
}

interface JSONData {
    meta: Array<{ options?: string }>;
}

export class FaustDspGenerator implements IFaustDspGenerator {
    private static compilerPromise: Promise<FaustCompiler> | null = null;

    // Analyze the metadata of a Faust JSON file and extract the [midi:on] and [nvoices:n] options
    private extractMidiAndNvoices(jsonData: JSONData): {
        midi: boolean;
        nvoices: number;
    } {
        const optionsMetadata = jsonData.meta.find((meta) => meta.options);
        if (optionsMetadata && optionsMetadata.options) {
            const options = optionsMetadata.options;

            const midiRegex = /\[midi:(on|off)\]/;
            const nvoicesRegex = /\[nvoices:(\d+)\]/;

            const midiMatch = options.match(midiRegex);
            const nvoicesMatch = options.match(nvoicesRegex);

            const midi = midiMatch ? midiMatch[1] === 'on' : false;
            const nvoices = nvoicesMatch ? parseInt(nvoicesMatch[1], 10) : -1;

            return { midi, nvoices };
        } else {
            return { midi: false, nvoices: -1 };
        }
    }

    /**
     * Compile DSP code, inspect metadata for [nvoices:] (and optionally [midi:on]), and build either a mono
     * or poly WebAudio node (ScriptProcessor or AudioWorklet depending on `sp`). Compilation uses a shared,
     * lazily-created libfaust instance to avoid repeatedly instantiating the WASM compiler.
     */
    async createFaustNode(
        context: BaseAudioContext,
        name: string,
        code: string,
        sp?: boolean,
        bufferSize?: number
    ): Promise<IFaustMonoWebAudioNode | IFaustPolyWebAudioNode | null> {
        const getCompiler = async () => {
            if (!FaustDspGenerator.compilerPromise) {
                // Resolve libfaust-wasm assets relative to current script/page location (works in browser and bundlers).
                // Falling back to document/baseURI keeps things working when import.meta.url is unavailable (es2019 target).
                const baseURL =
                    (typeof document !== 'undefined'
                        ? 'src' in (document.currentScript || {})
                            ? (document.currentScript as HTMLScriptElement).src
                            : document.baseURI
                        : undefined) ||
                    (typeof window !== 'undefined'
                        ? window.location.href
                        : undefined);
                if (!baseURL)
                    throw new Error('Cannot resolve libfaust-wasm location.');
                const jsURL = new URL(
                    '../libfaust-wasm/libfaust-wasm.js',
                    baseURL
                ).href;
                const dataURL = jsURL.replace(/c?js$/, 'data');
                const wasmURL = jsURL.replace(/c?js$/, 'wasm');
                FaustDspGenerator.compilerPromise =
                    instantiateFaustModuleFromFile(
                        jsURL,
                        dataURL,
                        wasmURL
                    ).then((module) => new FaustCompiler(new LibFaust(module)));
            }
            return FaustDspGenerator.compilerPromise;
        };

        const args = '-ftz 2';

        try {
            const compiler = await getCompiler();
            // First compile as mono to inspect metadata for nvoices/midi tags; if nvoices > 0 we recompile as poly.
            const monoGenerator = new FaustMonoDspGenerator();
            const compiledMono = await monoGenerator.compile(
                compiler,
                name,
                code,
                args
            );
            if (!compiledMono) return null;

            // Extract nvoices from metadata
            const { nvoices } = this.extractMidiAndNvoices(
                monoGenerator.getMeta() as unknown as JSONData
            );

            // If nvoices > 0, recompile as polyphonic
            if (nvoices > 0) {
                const polyGenerator = new FaustPolyDspGenerator();
                const compiledPoly = await polyGenerator.compile(
                    compiler,
                    name,
                    code,
                    args
                );
                if (!compiledPoly) return null;

                // Poly creation: combine voice/effect factories, create node with requested SP/AWN and buffer size.
                return await polyGenerator.createNode(
                    context,
                    nvoices,
                    name,
                    undefined,
                    undefined,
                    undefined,
                    sp,
                    bufferSize
                );
            }

            // Mono creation path when no polyphony hint is present.
            return await monoGenerator.createNode(
                context,
                name,
                undefined,
                sp,
                bufferSize
            );
        } catch (e) {
            console.error(e);
            return null;
        }
    }
}
